




"use strict";

const ModuleDependency = require("./ModuleDependency");




class LoaderImportDependency extends ModuleDependency {
	



	constructor(request) {
		super(request);
		
		this.weak = true;
	}

	get type() {
		return "loader import";
	}

	get category() {
		return "loaderImport";
	}

	




	getCondition(moduleGraph) {
		return false;
	}
}

module.exports = LoaderImportDependency;
